}

/**
 * Fetch validation results
 * AC: @ui-validation-view ac-1
 */
export async function fetchValidation(): Promise<ValidationResponse> {
	if (isStaticMode()) {
		return {
			valid: true,
			schemaErrors: [],
			refErrors: [],
			refWarnings: [],
			orphans: [],
			completenessWarnings: [],
			traitCycles: []
		};
