// Mode-aware wrapper pattern
export async function fetchData(params?: {...}): Promise<PaginatedResponse<DataType>> {
  if (isStaticMode()) {
    return fetchDataStatic(params);
  }

  const response = await fetch(`${API_BASE}/api/endpoint`, {
    headers: getProjectHeaders()
  });
  if (!response.ok) {
    await handleResponseError(response);
  }
  return response.json();
}

// Write operation with guard
export async function writeData(payload: any): Promise<void> {
  assertWritable('write data');

  const response = await fetch(`${API_BASE}/api/endpoint`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...getProjectHeaders()
    },
    body: JSON.stringify(payload)
  });
  if (!response.ok) {
    await handleResponseError(response);
  }
}
