    await loadData();
    if (!isStaticMode()) {
      subscribe(['topic:updates']);
      on('topic:updates', handleUpdate);
    }
  });

  onDestroy(() => {
    if (!isStaticMode()) {
      off('topic:updates', handleUpdate);
      unsubscribe(['topic:updates']);
    }
  });

  // Reload on project change
