    70→        args += ch;
    71→        continue;
    72→      }
    73→
    74→      if (ch === "(") {
    75→        depth += 1;
    76→        args += ch;
    77→        continue;
    78→      }
    79→
    80→      if (ch === ")") {
    81→        depth -= 1;
    82→        if (depth === 0) {
    83→          break;
    84→        }
    85→        args += ch;
    86→        continue;
    87→      }
    88→
    89→      args += ch;
    90→    }
    91→
    92→    calls.push({ firstArg: firstTopLevelArg(args) });
    93→    callPattern.lastIndex = i + 1;
    94→  }
    95→
    96→  return calls;
    97→}
    98→
    99→function firstTopLevelArg(args: string): string {
   100→  let depth = 0;
   101→  let quote: '"' | "'" | "`" | null = null;
   102→  let escaped = false;
   103→  let first = "";
   104→
   105→  for (let i = 0; i < args.length; i += 1) {
   106→    const ch = args[i];
   107→
   108→    if (quote) {
   109→      first += ch;
   110→      if (escaped) {
   111→        escaped = false;
   112→        continue;
   113→      }
   114→      if (ch === "\\") {
   115→        escaped = true;
   116→        continue;
   117→      }
   118→      if (ch === quote) {
   119→        quote = null;
   120→      }
   121→      continue;
   122→    }
   123→
   124→    if (ch === '"' || ch === "'" || ch === "`") {
   125→      quote = ch;
   126→      first += ch;
   127→      continue;
   128→    }
   129→
   130→    if (ch === "(" || ch === "[" || ch === "{") {
   131→      depth += 1;
   132→      first += ch;
   133→      continue;
   134→    }
   135→
   136→    if (ch === ")" || ch === "]" || ch === "}") {
   137→      depth -= 1;
   138→      first += ch;
   139→      continue;
   140→    }
   141→
   142→    if (ch === "," && depth === 0) {
   143→      break;
   144→    }
   145→
   146→    first += ch;
   147→  }
   148→
   149→  return first.trim();
   150→}
   151→
   152→function extractSourceReference(text: string): string | null {
   153→  const directSrcMatch = text.match(/['"`]([^'"`]*(?:^|\/)src\/[^'"`]*)['"`]/);
   154→  if (directSrcMatch?.[1]) {
   155→    return directSrcMatch[1];
   156→  }
   157→
   158→  const directPackagesMatch = text.match(
   159→    /['"`]([^'"`]*packages\/[^'"`]+\/src\/[^'"`]*)['"`]/,
   160→  );
   161→  if (directPackagesMatch?.[1]) {
   162→    return directPackagesMatch[1];
   163→  }
   164→
   165→  if (/(?:path\.)?(?:join|resolve)\([\s\S]*?['"`]src['"`]/.test(text)) {
   166→    const segments = [...text.matchAll(/['"`]([^'"`]+)['"`]/g)].map(
   167→      (m) => m[1],
   168→    );
   169→
   170→    if (segments.includes("src")) {
   171→      return segments.join("/");
   172→    }
   173→  }
   174→
   175→  if (
   176→    /(?:path\.)?(?:join|resolve)\([\s\S]*?['"`]packages['"`][\s\S]*?['"`]src['"`]/.test(
   177→      text,
   178→    )
   179→  ) {
   180→    const segments = [...text.matchAll(/['"`]([^'"`]+)['"`]/g)].map(
   181→      (m) => m[1],
   182→    );
   183→    return segments.join("/");
   184→  }
   185→
   186→  return null;
   187→}
   188→
   189→function collectSourceVariableHints(content: string): Map<string, string> {
   190→  const hints = new Map<string, string>();
   191→  const varPattern = /\b(?:const|let)\s+([A-Za-z_$][\w$]*)\s*=([\s\S]*?);/g;
   192→  let match: RegExpExecArray | null = null;
   193→
   194→  while ((match = varPattern.exec(content)) !== null) {
   195→    const variableName = match[1];
   196→    const initializer = match[2];
   197→    const sourceRef = extractSourceReference(initializer);
   198→    if (sourceRef) {
   199→      hints.set(variableName, sourceRef);
   200→    }
   201→  }
   202→
   203→  const forOfPattern =
   204→    /for\s*\(\s*const\s+([A-Za-z_$][\w$]*)\s+of\s+([A-Za-z_$][\w$]*)\s*\)/g;
   205→  while ((match = forOfPattern.exec(content)) !== null) {
   206→    const itemVariable = match[1];
   207→    const iterableVariable = match[2];
   208→    const iterableHint = hints.get(iterableVariable);
   209→    if (iterableHint) {
   210→      hints.set(itemVariable, iterableHint);
   211→    }
   212→  }
   213→
   214→  return hints;
   215→}
   216→
   217→function resolveReferencedSourcePath(
   218→  expression: string,
   219→  sourceHints: Map<string, string>,
   220→): string | null {
   221→  const directReference = extractSourceReference(expression);
   222→  if (directReference) {
   223→    return directReference;
   224→  }
   225→
   226→  for (const [variableName, sourceHint] of sourceHints.entries()) {
   227→    if (new RegExp(`\\b${variableName}\\b`).test(expression)) {
   228→      return sourceHint;
   229→    }
   230→  }
   231→
   232→  return null;
   233→}
   234→
   235→describe("no static analysis test pattern", () => {
   236→  it("does not allow tests to read implementation source files", () => {
   237→    const violations = new Set<string>();
   238→    const testFiles = listTestFiles(TESTS_DIR);
   239→
   240→    for (const testFilePath of testFiles) {
   241→      const content = readFileSync(testFilePath, "utf-8");
   242→      const sourceHints = collectSourceVariableHints(content);
   243→      const readCalls = parseReadCalls(content);
   244→
   245→      for (const readCall of readCalls) {
   246→        const sourcePath = resolveReferencedSourcePath(
   247→          readCall.firstArg,
   248→          sourceHints,
   249→        );
   250→        if (!sourcePath) {
   251→          continue;
   252→        }
   253→
   254→        const relativePath = relative(process.cwd(), testFilePath);
   255→        violations.add(
   256→          `Test file ${relativePath} reads source file ${sourcePath}. Tests should exercise behavior (import functions, call CLI, make HTTP requests) not scan source code for string patterns.`,
   257→        );
   258→      }
   259→    }
   260→
   261→    expect([...violations].sort()).toEqual([]);
   262→  });
   263→});
   264→
